INSERT IGNORE INTO diagnosis_scenarios (id,robot_id,title,context_text,symptom_text,explanation_text,state,version_no,created_by,created_at,published_at,guide_id) VALUES (6101,'obstacle-avoider','Bánh trái không quay khi chạy thử','Robot tránh vật cản được đặt trên giá thử; chương trình đang yêu cầu hai bánh tiến với cùng tốc độ.','Bánh phải quay đều nhưng bánh trái đứng yên trong lần chạy thử.','Dữ kiện khoanh vùng tới đầu nối động cơ trái: nguồn và tín hiệu L298N đều đúng, nhưng đường OUT1–OUT2 bị lỏng. Ngắt nguồn, siết đầu nối rồi thử lại; không tăng PWM để bù lỗi dây.','PUBLISHED',1,@seed_admin,UTC_TIMESTAMP(),UTC_TIMESTAMP(),(SELECT id FROM troubleshooting_guides WHERE id='wheel-not-spinning' AND (robot_id='obstacle-avoider' OR robot_id IS NULL)));
INSERT IGNORE INTO diagnosis_checks (id,scenario_id,label,observation_text,is_required,display_order) VALUES (61011,6101,'Kiểm tra đầu nối động cơ trái','Khi đã ngắt nguồn, đầu nối OUT1–OUT2 tới động cơ trái bị lỏng; dây động cơ phải chắc chắn.',1,1);
INSERT IGNORE INTO diagnosis_checks (id,scenario_id,label,observation_text,is_required,display_order) VALUES (61012,6101,'Kiểm tra tín hiệu điều khiển L298N','ENA ở D5 có PWM, IN1 D6 và IN2 D7 có mức điều khiển tiến đúng; nguồn động cơ ổn định và GND chung.',1,2);
INSERT IGNORE INTO diagnosis_checks (id,scenario_id,label,observation_text,is_required,display_order) VALUES (61013,6101,'Đọc khoảng cách HC-SR04','Khoảng cách đo không có vật cản gần; phép này không xác định được sự gián đoạn ở dây động cơ.',0,3);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61011,6101,'CAUSE','Đầu nối động cơ trái bị lỏng','Đầu nối lỏng làm đường cấp dòng tới động cơ trái bị gián đoạn dù tín hiệu điều khiển đúng.',1,1);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61012,6101,'CAUSE','Nguồn động cơ mất hoàn toàn','Nguồn được kiểm tra ổn định và bánh phải vẫn quay; dữ kiện không phù hợp với mất nguồn toàn bộ.',0,2);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61013,6101,'CAUSE','HC-SR04 phát hiện vật cản','Không có vật cản gần; kiểm tra cảm biến không giải thích đầu nối động cơ bị gián đoạn.',0,3);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61016,6101,'ACTION','Ngắt nguồn và siết lại đầu nối động cơ trái','Ngắt nguồn trước khi chỉnh đầu nối, siết chắc và chạy thử lại hai bánh.',1,1);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61017,6101,'ACTION','Tăng PWM tối đa cho cả hai bánh','PWM cao hơn không sửa được đầu nối lỏng.',0,2);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61018,6101,'ACTION','Đổi chân TRIG và ECHO','TRIG D11 và ECHO D12 thuộc phép đo khoảng cách, không sửa dây động cơ.',0,3);
INSERT IGNORE INTO diagnosis_scenarios (id,robot_id,title,context_text,symptom_text,explanation_text,state,version_no,created_by,created_at,published_at,guide_id) VALUES (6102,'obstacle-avoider','Robot bắt đầu tránh vật cản quá xa','Robot tránh vật cản chạy trong lối thử với các vật đặt ở nhiều khoảng cách; tốc độ thử không đổi.','Robot dừng và rẽ dù vật cản còn cách xa vùng cần tránh.','Nguyên nhân là ngưỡng chương trình, không phải đo khoảng cách. Số đo 60 cm đúng nhưng vẫn nhỏ hơn ngưỡng 100 cm. Cần đặt ngưỡng 20 cm và kiểm thử hai phía của ngưỡng để xác nhận hành vi.','PUBLISHED',1,@seed_admin,UTC_TIMESTAMP(),UTC_TIMESTAMP(),(SELECT id FROM troubleshooting_guides WHERE id='obstacle-avoider-false-trigger' AND (robot_id='obstacle-avoider' OR robot_id IS NULL)));
INSERT IGNORE INTO diagnosis_checks (id,scenario_id,label,observation_text,is_required,display_order) VALUES (61021,6102,'So sánh số đo với khoảng cách chuẩn','Vật đặt cách 60 cm, HC-SR04 trả khoảng 60 cm; TRIG D11 và ECHO D12 nối đúng theo sơ đồ.',1,1);
INSERT IGNORE INTO diagnosis_checks (id,scenario_id,label,observation_text,is_required,display_order) VALUES (61022,6102,'Kiểm tra ngưỡng khoảng cách trong chương trình','Điều kiện tránh đang dùng khoảng cách nhỏ hơn 100 cm; bài thử yêu cầu ngưỡng 20 cm.',1,2);
INSERT IGNORE INTO diagnosis_checks (id,scenario_id,label,observation_text,is_required,display_order) VALUES (61023,6102,'Kiểm tra đầu nối bánh trái','Hai đầu nối động cơ chắc chắn và hai bánh chạy đúng chiều khi không có vật trong vùng ngưỡng.',0,3);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61021,6102,'CAUSE','Ngưỡng tránh vật cản đặt quá lớn','Số đo đúng nhưng ngưỡng 100 cm khiến vật ở 60 cm bị coi là quá gần.',1,1);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61022,6102,'CAUSE','TRIG và ECHO bị đảo','Chân nối đúng và số đo khớp khoảng cách chuẩn, không hỗ trợ giả thuyết đảo chân.',0,2);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61023,6102,'CAUSE','Động cơ trái bị đứt dây','Hai bánh đều chạy đúng trong phép thử độc lập.',0,3);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61026,6102,'ACTION','Đặt ngưỡng 20 cm và kiểm tra lại ở hai phía ngưỡng','Đổi ngưỡng theo yêu cầu, thử vật gần và xa hơn 20 cm để kiểm chứng điều kiện.',1,1);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61027,6102,'ACTION','Thay đầu nối động cơ trái','Đầu nối đã được kiểm tra và không liên quan điều kiện khoảng cách.',0,2);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61028,6102,'ACTION','Đảo TRIG và ECHO trên Arduino','Chân đúng theo sơ đồ; đảo chân sẽ gây lỗi đo mới.',0,3);
INSERT IGNORE INTO diagnosis_scenarios (id,robot_id,title,context_text,symptom_text,explanation_text,state,version_no,created_by,created_at,published_at,guide_id) VALUES (6103,'line-follower','Robot không phân biệt vạch trên đường thử','Robot dò line được đặt trên mặt đường thử có vạch đen và nền sáng; chương trình đọc hai cảm biến trái và phải.','Robot đi thẳng qua vạch và không thay đổi điều khiển khi chuyển từ nền sáng sang vạch đen.','Hai cảm biến được cấp nguồn và nối OUT đúng nhưng lắp quá cao so với vùng đọc. Việc hạ cảm biến làm tín hiệu đổi theo vạch/nền chứng minh nguyên nhân vị trí; cần kiểm lại hai trạng thái trước khi chạy.','PUBLISHED',1,@seed_admin,UTC_TIMESTAMP(),UTC_TIMESTAMP(),(SELECT id FROM troubleshooting_guides WHERE id='line-not-detected' AND (robot_id='line-follower' OR robot_id IS NULL)));
INSERT IGNORE INTO diagnosis_checks (id,scenario_id,label,observation_text,is_required,display_order) VALUES (61031,6103,'Kiểm tra vị trí cảm biến so với mặt đường','Hai cảm biến đang lắp quá cao; khi hạ vào vùng đọc của module, tín hiệu đổi giữa vạch và nền.',1,1);
INSERT IGNORE INTO diagnosis_checks (id,scenario_id,label,observation_text,is_required,display_order) VALUES (61032,6103,'Kiểm tra dây OUT và nguồn cảm biến','OUT trái nối D2, OUT phải nối D3; VCC 5V và GND chung đều đúng, dây không bị lỏng.',1,2);
INSERT IGNORE INTO diagnosis_checks (id,scenario_id,label,observation_text,is_required,display_order) VALUES (61033,6103,'Đọc khoảng cách phía trước','Mẫu dò line này không dùng HC-SR04; số đo phía trước không giúp kiểm tra phản xạ ở vạch.',0,3);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61031,6103,'CAUSE','Cảm biến line lắp ngoài vùng đọc của module','Tín hiệu đổi sau khi hạ cảm biến cho thấy vị trí lắp gây lỗi nhận vạch.',1,1);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61032,6103,'CAUSE','Hai dây OUT đều bị ngắt','Kiểm tra xác nhận OUT D2/D3 nối chắc và phản hồi đúng sau khi chỉnh vị trí.',0,2);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61033,6103,'CAUSE','Cảm biến khoảng cách báo sai','Mẫu robot này không dùng cảm biến khoảng cách để nhận vạch.',0,3);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61036,6103,'ACTION','Chỉnh độ cao cảm biến và thử lại trên vạch cùng nền','Đặt trong vùng đọc của module rồi kiểm tra cả vạch và nền trước khi chạy.',1,1);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61037,6103,'ACTION','Thêm lệnh bỏ qua tín hiệu D2 và D3','Bỏ qua hai tín hiệu sẽ làm robot mất căn cứ dò vạch.',0,2);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61038,6103,'ACTION','Đổi chân PWM của L298N','PWM không giải quyết vị trí lắp của cảm biến line.',0,3);
INSERT IGNORE INTO diagnosis_scenarios (id,robot_id,title,context_text,symptom_text,explanation_text,state,version_no,created_by,created_at,published_at,guide_id) VALUES (6104,'mini-arm','Servo khớp đầu không chuyển động','Tay máy mini nhận lệnh đổi góc một khớp trong bài thử; các khớp còn lại đang ở vị trí giữ ổn định.','Servo của khớp đang thử không đổi góc dù đã gửi lệnh mới.','Lỗi nằm ở đường nguồn riêng của servo đang thử. Xung tín hiệu và GND đã đúng nhưng VCC bị tuột. Ngắt nguồn, nối lại nguồn 5V riêng và thử chuyển động nhỏ; không dùng chân 5V Arduino thay nguồn toàn bộ servo.','PUBLISHED',1,@seed_admin,UTC_TIMESTAMP(),UTC_TIMESTAMP(),(SELECT id FROM troubleshooting_guides WHERE id='servo-no-response' AND (robot_id='mini-arm' OR robot_id IS NULL)));
INSERT IGNORE INTO diagnosis_checks (id,scenario_id,label,observation_text,is_required,display_order) VALUES (61041,6104,'Kiểm tra nguồn riêng tới servo đang thử','Đã ngắt nguồn trước khi kiểm tra: đầu nối VCC của servo đang thử bị tuột khỏi nguồn 5V riêng.',1,1);
INSERT IGNORE INTO diagnosis_checks (id,scenario_id,label,observation_text,is_required,display_order) VALUES (61042,6104,'Kiểm tra tín hiệu và mốc GND','Chân tín hiệu đúng theo sơ đồ tay máy, có xung điều khiển; GND nguồn servo và Arduino đã nối chung.',1,2);
INSERT IGNORE INTO diagnosis_checks (id,scenario_id,label,observation_text,is_required,display_order) VALUES (61043,6104,'Kiểm tra giá trị cảm biến line','Tay máy không dùng cảm biến line để điều khiển góc servo; phép này không liên quan.',0,3);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61041,6104,'CAUSE','Đầu nối nguồn VCC của servo đang thử bị tuột','Servo không nhận nguồn dù tín hiệu và GND đúng.',1,1);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61042,6104,'CAUSE','Mất chung GND với Arduino','Kiểm tra xác nhận GND nguồn riêng và Arduino đã chung.',0,2);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61043,6104,'CAUSE','Cảm biến line đọc nền sai','Tình huống tay máy không sử dụng cảm biến line.',0,3);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61046,6104,'ACTION','Ngắt nguồn và nối lại VCC vào nguồn 5V riêng của servo','Nối chắc VCC nguồn riêng và giữ GND chung, rồi thử một chuyển động nhỏ.',1,1);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61047,6104,'ACTION','Cấp mọi servo từ chân 5V Arduino thay nguồn riêng','Sơ đồ dùng nguồn servo riêng; chuyển toàn bộ tải sang Arduino không sửa đúng đầu nối.',0,2);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61048,6104,'ACTION','Tăng góc lệnh liên tục đến giới hạn','Lệnh góc không thể bù việc servo không nhận nguồn.',0,3);
INSERT IGNORE INTO diagnosis_scenarios (id,robot_id,title,context_text,symptom_text,explanation_text,state,version_no,created_by,created_at,published_at,guide_id) VALUES (6105,'line-obstacle','Robot tiếp tục bám vạch khi có vật cản gần','Robot kết hợp dò line và tránh vật cản đang chạy trên vạch với một vật thử đặt phía trước.','Robot vẫn tiến theo vạch khi vật thử ở trong ngưỡng tránh đã đặt.','Cả hai loại cảm biến hoạt động nhưng nhánh dò line kết thúc xử lý trước khi xét khoảng cách. Cần ưu tiên tránh vật cản gần, rồi tìm lại vạch bằng tín hiệu line; các cảm biến phải có thứ tự ưu tiên rõ ràng.','PUBLISHED',1,@seed_admin,UTC_TIMESTAMP(),UTC_TIMESTAMP(),(SELECT id FROM troubleshooting_guides WHERE id='line-obstacle-loses-track' AND (robot_id='line-obstacle' OR robot_id IS NULL)));
INSERT IGNORE INTO diagnosis_checks (id,scenario_id,label,observation_text,is_required,display_order) VALUES (61051,6105,'Kiểm tra các số đo cảm biến khi gặp vật cản','Hai cảm biến line thấy vạch; HC-SR04 đo 10 cm với vật đặt ở 10 cm, ngưỡng an toàn của bài thử là 20 cm.',1,1);
INSERT IGNORE INTO diagnosis_checks (id,scenario_id,label,observation_text,is_required,display_order) VALUES (61052,6105,'Theo dõi thứ tự xử lý điều kiện trong chương trình','Nhánh thấy vạch ra lệnh tiến và kết thúc vòng xử lý trước khi xét điều kiện vật cản gần.',1,2);
INSERT IGNORE INTO diagnosis_checks (id,scenario_id,label,observation_text,is_required,display_order) VALUES (61053,6105,'Kiểm tra đầu nối động cơ','Hai động cơ phản hồi đúng khi thử tiến và dừng; đầu nối L298N đều chắc.',0,3);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61051,6105,'CAUSE','Nhánh dò line được ưu tiên trước tránh vật cản','Điều kiện vật cản gần đúng nhưng không được xử lý vì nhánh dò line kết thúc sớm.',1,1);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61052,6105,'CAUSE','HC-SR04 bị đảo TRIG và ECHO','Số đo khớp khoảng cách chuẩn; dữ kiện chỉ ra lỗi ưu tiên điều kiện.',0,2);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61053,6105,'CAUSE','Cả hai đầu nối động cơ bị lỏng','Hai động cơ đã phản hồi đúng trong phép kiểm tra độc lập.',0,3);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61056,6105,'ACTION','Xét vật cản gần trước, né an toàn rồi dùng cảm biến tìm lại vạch','Ưu tiên dừng hoặc tránh khi gần vật cản, sau đó giảm tốc và dùng line tìm lại quỹ đạo.',1,1);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61057,6105,'ACTION','Bỏ qua HC-SR04 khi đang thấy vạch','Đây chính là cách ưu tiên sai đang gây lỗi.',0,2);
INSERT IGNORE INTO diagnosis_options (id,scenario_id,kind,label,feedback_text,is_correct,display_order) VALUES (61058,6105,'ACTION','Tăng PWM để đi qua vật cản','Tăng tốc không giải quyết điều kiện ưu tiên và không phù hợp bài thử.',0,3);
